<!doctype html><html><head><meta charset="utf-8"><style>body{font-family:DejaVu Sans,sans-serif;color:#222;font-size:11px;margin:28px}h1{text-align:center;font-size:20px}h2{font-size:14px;margin-top:18px}.meta{text-align:center;color:#666;margin-bottom:20px}.text{white-space:pre-line;line-height:1.5}table{width:100%;border-collapse:collapse;margin-top:10px}th{background:#283d4d;color:#fff}th,td{border:1px solid #bbb;padding:7px}td:nth-child(2),td:nth-child(3){text-align:center;width:80px}.total{font-weight:bold;background:#eee}.footer{margin-top:20px;color:#666;font-size:9px}</style></head><body><h1>Feedback Format</h1><div class="meta"><strong>{{$feedback->department->name}}</strong> · {{\App\Models\EdrReport::periodLabel($feedback->reporting_period)}} · {{$feedback->year}}</div><h2>Strength</h2><div class="text">{{$feedback->strengths?:'Not provided.'}}</div><h2>Weakness</h2><div class="text">{{$feedback->weaknesses?:'Not provided.'}}</div><h2>Next Focus Areas</h2><div class="text">{{$feedback->next_focus_areas?:'Not provided.'}}</div><h2>EDR Departments Evaluation Ranking Criteria</h2><table><thead><tr><th>No.</th><th>Criteria</th><th>Weight</th><th>Score</th></tr></thead><tbody><tr><td>1</td><td>Plan Quality</td><td>5</td><td>{{$feedback->plan_quality_score}}</td></tr><tr><td>2</td><td>Report Quality</td><td>8</td><td>{{$feedback->report_quality_score}}</td></tr><tr><td>3</td><td>Plan and Report Submission Date</td><td>7</td><td>{{$feedback->submission_score}}</td></tr><tr><td>4</td><td>Performance based on approved plan ({{$feedback->performance_percent??'N/A'}}%)</td><td>80</td><td>{{$feedback->performance_score??'Pending'}}</td></tr><tr class="total"><td></td><td>Total</td><td>100</td><td>{{\App\Support\NumberFormatter::format($feedback->total_score,3)}}</td></tr></tbody></table><div class="footer">Prepared by {{$feedback->preparer?->name??'Not recorded'}} · Generated {{now()->format('d M Y H:i')}}</div></body></html>
